describe('Font Size Readability on Small Screens', () => {
  beforeEach(() => {
    cy.visit('/page');
  });

  it('should display readable font size on small screen without zooming', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="heading-1"]').should('contain', 'Page Title');
    cy.get('[data-testid="paragraph-text"]').should('contain', 'This is a paragraph of text');
    cy.get('[data-testid="paragraph-text"]').should('have.css', 'font-size').and('include', '16px');
    cy.get('[data-testid="heading-1"]').should('have.css', 'font-size').and('include', '24px');
    cy.get('[data-testid="body-text"]').should('have.css', 'font-size').and('include', '16px');
    cy.get('[data-testid="body-text"]').should('be.visible');
    cy.get('[data-testid="body-text"]').should('not.be.hidden');
  });

  it('should maintain readable font size when screen is resized to small mobile view', () => {
    cy.viewport('ipad-2');
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="paragraph-text"]').should('contain', 'This is a paragraph of text');
    cy.get('[data-testid="paragraph-text"]').should('have.css', 'font-size').and('include', '16px');
    cy.viewport('iphone-12');
    cy.get('[data-testid="paragraph-text"]').should('have.css', 'font-size').and('include', '16px');
    cy.get('[data-testid="heading-1"]').should('have.css', 'font-size').and('include', '24px');
    cy.get('[data-testid="heading-1"]').should('be.visible');
    cy.get('[data-testid="body-text"]').should('be.visible');
  });
});
